import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as a,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"MoE 与前沿架构（桥接）","description":"MoE 把参数量与计算量解耦、MLA 压缩 KV cache、长上下文改变检索经济学——本页给应用工程师位置感：这些架构决定 API 定价/速度/上下文策略的「为什么」；推导桥接 Learn LLM 第 9/20 章。","frontmatter":{"title":"MoE 与前沿架构（桥接）","description":"MoE 把参数量与计算量解耦、MLA 压缩 KV cache、长上下文改变检索经济学——本页给应用工程师位置感：这些架构决定 API 定价/速度/上下文策略的「为什么」；推导桥接 Learn LLM 第 9/20 章。","domain":"tech","tags":["tech","moe","architecture","bridge","long-context"],"navOrder":93,"topicId":"moe-frontier","layer":"9","status":"bridge","nodeType":"boundary","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/"}],"lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"zh/tech/09-advanced/moe-frontier.md","filePath":"zh/tech/09-advanced/moe-frontier.md","lastUpdated":1791123021000}'),n={name:"zh/tech/09-advanced/moe-frontier.md"};function d(i,t,l,s,h,c){return a(),r("div",null,[...t[0]||(t[0]=[o('<blockquote><p><strong>所在组</strong>：进阶（桥接） ｜ <strong>上一组出口</strong>：能用发布门与版本化纪律长期运行 ｜ <strong>本页出口</strong>：知道该主题影响哪个工程决策、何时去 Learn LLM</p></blockquote><h1 id="moe-与前沿架构-桥接" tabindex="-1">MoE 与前沿架构（桥接） <a class="header-anchor" href="#moe-与前沿架构-桥接" aria-label="Permalink to &quot;MoE 与前沿架构（桥接）&quot;">​</a></h1><blockquote><p><strong>桥接页</strong>：MoE 路由、负载均衡、MLA 的注意力推导、长上下文的位置编码在 <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a>（第 9 章 · 推理与量化；第 20 章 · DeepSeek 模型专题）。本仓只保留应用侧的位置感：<strong>这些架构解释了你选型表里价格、速度、上下文上限的「为什么」。</strong></p></blockquote><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>解决什么问题</strong>：三个前沿架构方向各自打破一条旧的等式：</p><ul><li><strong>MoE</strong>（Mixture-of-Experts）打破「参数多 = 每次计算多」：总参数可以巨大，但每个 token 只激活一小部分专家——容量与单次成本解耦。</li><li><strong>MLA</strong>（Multi-head Latent Attention）打破「长上下文 = KV cache 线性爆炸」：把 KV 压缩到低维潜在空间，长上下文的推理成本曲线变平缓。</li><li><strong>长上下文</strong>打破「模型一次只能看一小段」：但「能放进」不等于「用得好」——长输入中间段的信息利用率有已知的下降形态。</li></ul><p><strong>为什么应用工程师要有位置感</strong>：你不需要会推 MLA，但选型表上「为什么这家便宜」「为什么那个快」「上下文该塞多满」的答案都来自这三条。不理解它们，选型就退化为背价格表。</p><h2 id="_2-使用" tabindex="-1">2. 使用 <a class="header-anchor" href="#_2-使用" aria-label="Permalink to &quot;2. 使用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>决策</th><th>架构给的位置感</th></tr></thead><tbody><tr><td>API 选型（价格/速度）</td><td>MoE 模型的单 token 成本由<strong>激活参数</strong>而非总参数决定——「总参数巨大」不是贵的理由，「激活参数大」才是；托管 API 已把这层消化进定价</td></tr><tr><td>托管 vs 自托管</td><td>MoE 省计算不省显存：全部专家权重都要驻留内存。自托管 MoE 的门槛在显存与通信，不在算力——这是「托管便宜、自托管贵」悖论的来源之一</td></tr><tr><td>上下文策略</td><td>长上下文 ≠ 免费的 RAG 替代：塞满窗口的成本与中间段利用率下降都是真实代价。纲领不变——「检索该做的事交给检索」（→<a href="./../04-grounding/">04-grounding</a>），长窗口用来放<strong>必须整段在场</strong>的东西（合同全文、长代码文件）</td></tr><tr><td>KV cache 相关成本</td><td>缓存命中与上下文前缀复用（prompt caching）的价值随架构不同；对长上下文+多轮场景，前缀稳定是省钱的工程手段（→<a href="./../08-production/cost-performance.html">成本与性能</a>）</td></tr></tbody></table><h2 id="_3-原理" tabindex="-1">3. 原理 <a class="header-anchor" href="#_3-原理" aria-label="Permalink to &quot;3. 原理&quot;">​</a></h2><p>（本段刻意极简：推导归 Learn LLM。）</p><ul><li><strong>MoE</strong> 一句话：路由器为每个 token 挑少量专家计算，容量涨、单次计算不涨；代价是负载均衡与路由稳定性。</li><li><strong>MLA</strong> 一句话：把 KV 压进低维潜在表示再按需还原，是 MQA/GQA 压缩路线的延伸。</li><li><strong>长上下文</strong> 一句话：窗口能放大，但中间段利用率下降（lost-in-the-middle 现象）——位置在上下文里放哪仍是工程变量。</li></ul><p>深水区：Learn LLM 第 9 章（KV cache、MQA/GQA）、第 20 章（DeepSeek 专题：MLA/MoE/GRPO）。</p><h2 id="_4-开发" tabindex="-1">4. 开发 <a class="header-anchor" href="#_4-开发" aria-label="Permalink to &quot;4. 开发&quot;">​</a></h2><p><strong>症状 → 去哪</strong>：</p><ul><li>「换了号称更强的模型，账单反而变了」→ 用激活参数视角重算单位成本（→<a href="./../08-production/cost-performance.html">成本与性能</a>）。</li><li>「百万上下文模型还需要 RAG 吗」→ 需要。私有/新鲜事实的 grounding 问题不因窗口变大消失（→<a href="./../04-grounding/">04-grounding</a>）；长窗口改变的是「整段在场」类场景的可行性。</li><li>「长文档中间的关键信息总被漏掉」→ 位置策略：关键信息放头尾、或结构化分块再检索，不要指望满窗口均匀注意力。</li><li>想懂路由/MLA 推导 → Learn LLM 第 9、20 章。</li></ul><h2 id="_5-资料库" tabindex="-1">5. 资料库 <a class="header-anchor" href="#_5-资料库" aria-label="Permalink to &quot;5. 资料库&quot;">​</a></h2><p>一手源（只引编号，不复述内容）：</p><table tabindex="0"><thead><tr><th>名称</th><th>来源</th><th>标识</th></tr></thead><tbody><tr><td>Outrageously Large Neural Networks（稀疏 MoE 起点）</td><td>Shazeer et al.</td><td>arXiv:1701.06538</td></tr><tr><td>Switch Transformers（Top-1 路由）</td><td>Fedus / Zoph / Shazeer</td><td>arXiv:2101.03961</td></tr><tr><td>Mixtral of Experts（开源 MoE 代表）</td><td>Mistral AI</td><td>arXiv:2401.04088</td></tr><tr><td>DeepSeek-V2（MLA 提出）</td><td>DeepSeek-AI</td><td>arXiv:2405.04434</td></tr><tr><td>DeepSeek-V3 Technical Report</td><td>DeepSeek-AI</td><td>arXiv:2412.19437</td></tr><tr><td>Lost in the Middle（长上下文位置效应）</td><td>Liu et al.</td><td>arXiv:2307.03172</td></tr></tbody></table><p>（retrievedAt 2026-09-01；各模型的当前架构细节以其技术报告与官方文档为准。）</p><h3 id="learn-ai-到此为止-继续去哪" tabindex="-1">learn-ai 到此为止 / 继续去哪 <a class="header-anchor" href="#learn-ai-到此为止-继续去哪" aria-label="Permalink to &quot;learn-ai 到此为止 / 继续去哪&quot;">​</a></h3><ul><li>MoE/MLA/GRPO 的推导与 toy 复现：<a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a> 第 20 章（DeepSeek 模型专题），先修第 9 章（推理与量化）。</li><li>上下文工程的落点：<a href="./../03-context/">03-context</a>；成本收口：<a href="./../08-production/">08-production</a>。</li></ul>',22)])])}const L=e(n,[["render",d]]);export{m as __pageData,L as default};
